 1 | import { isThemeBgToken, isThemeColorToken, theme } from "../theme/theme.ts";
 2 | import { customBackground, customForeground } from "./appearance-colors.ts";
 3 | import type { AppearanceColor } from "./appearance-types.ts";
 4 | 
 5 | export type AppearanceColorRole = "fg" | "bg";
 6 | 
 7 | /**
 8 |  * One shared presentation-level resolver for AppearanceColor (F1).
 9 |  *
10 |  * - theme: resolve the exact validated semantic token dynamically against the
11 |  *   live theme, so switching themes updates appearance without rewriting it.
12 |  * - custom: validated HEX/RGB/HSL mapped to ANSI fg/bg functions.
13 |  * - terminal-default: terminal default fg/bg (reset-only wrappers).
14 |  * - none: transparent, no styling.
15 |  *
16 |  * Foreground/background usage stays distinct via `role`.
17 |  */
18 | export function resolveAppearanceColorFn(color: AppearanceColor, role: AppearanceColorRole): (text: string) => string {
19 | 	switch (color.kind) {
20 | 		case "custom":
21 | 			return role === "bg" ? customBackground(color.value) : customForeground(color.value);
22 | 		case "theme": {
23 | 			if (role === "bg") {
24 | 				if (isThemeBgToken(color.token)) {
25 | 					const token = color.token;
26 | 					return (text: string) => theme.bg(token, text);
27 | 				}
28 | 				return (text: string) => text;
29 | 			}
30 | 			if (isThemeColorToken(color.token)) {
31 | 				const token = color.token;
32 | 				return (text: string) => theme.fg(token, text);
33 | 			}
34 | 			return (text: string) => text;
35 | 		}
36 | 		case "terminal-index": {
37 | 			const index = color.index;
38 | 			return role === "bg"
39 | 				? (text: string) => `\x1b[48;5;${index}m${text}\x1b[49m`
40 | 				: (text: string) => `\x1b[38;5;${index}m${text}\x1b[39m`;
41 | 		}
42 | 		case "terminal-default":
43 | 			return role === "bg" ? (text: string) => `${text}\x1b[49m` : (text: string) => `${text}\x1b[39m`;
44 | 		case "none":
45 | 			return (text: string) => text;
46 | 	}
47 | }
48 | 
49 | /** Extract ANSI open/close sequences from the shared color resolver. */
50 | export function resolveAppearanceColorDecoration(
51 | 	color: AppearanceColor,
52 | 	role: AppearanceColorRole,
53 | ): { prefix: string; suffix: string } {
54 | 	const sentinel = "\u0000";
55 | 	const styled = resolveAppearanceColorFn(color, role)(sentinel);
56 | 	const index = styled.indexOf(sentinel);
57 | 	if (index < 0) return { prefix: "", suffix: "" };
58 | 	return {
59 | 		prefix: styled.slice(0, index),
60 | 		suffix: styled.slice(index + sentinel.length),
61 | 	};
62 | }
63 | 
