19 | 		.split("/")
20 | 		.map((k) =>
21 | 			k
22 | 				.split("+")
23 | 				.map((part) => formatKeyPart(part, options))
24 | 				.join("+"),
25 | 		)
26 | 		.join("/");
27 | }
28 | 
29 | function formatKeys(keys: KeyId[], options: KeyTextFormatOptions = {}): string {
30 | 	if (keys.length === 0) return "";
31 | 	return formatKeyText(keys.join("/"), options);
32 | }
